from swegemma.evaluate import Evaluator  # noqa: E402
from swegemma.models.discovery import validate_single_declared_model  # noqa: E402

litellm.drop_params = True

# --- Sandbox environment fix for Kaggle (inserted into kernel templates) -------------------------
# Problem (council review E1): on Kaggle the subprocess sandbox inherits the notebook image's
# site-packages and the harness skips dependency installation; src-layout repos (requests, httpx)
# are not importable from /workspace, so tests import the image's preinstalled copy instead of the
# agent's patched code. Fix: per sandbox, try an editable install of /workspace (build backends from
# the competition wheels) and always add a .pth that puts /workspace/src and /workspace AHEAD of the
# system dist-packages (venv site-packages .pth entries are processed before system site dirs).
import shlex as _shlex

from swegemma.harness import agent_runner as _ar, container_setup as _cs, verification as _vf
from swegemma.sandbox.subprocess import SubprocessManager as _SM

_COMP_WHEELS = DATA / "wheels"
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "--no-index", f"--find-links={_COMP_WHEELS}",
                "hatchling", "pdm-backend", "flit-core", "poetry-core", "editables", "setuptools", "wheel"],
               capture_output=True)
_orig_install = _cs.install_test_dependencies


def _install_test_dependencies(docker, container_id, repo="", *, fast_path=True, config=None):
    if not isinstance(docker, _SM):
        return _orig_install(docker, container_id, repo, fast_path=fast_path, config=config)
    paths = docker.sandboxes[container_id]
    sp = next(paths["venv"].glob("lib/python*/site-packages"))
    ws = paths["workspace"]
    docker.exec(container_id, "cd /workspace && python3 -m pip install -q --disable-pip-version-check --no-index "
                              "--find-links=/wheels --no-build-isolation --no-deps -e . 2>&1 | tail -2")
    entries = [str(ws / "src")] if (ws / "src").is_dir() else []
    entries.append(str(ws))
    (sp / "000_workspace_first.pth").write_text("\n".join(entries) + "\n")
    # NOTE: do not run sandbox/setup.py --fast-path here: it puts every workspace subdirectory on
    # sys.path (e.g. fastapi/requests.py then shadows the real `requests`) - kverify-fix v1 lost all
    # 67 fastapi gold passes that way.


for _m in (_cs, _vf, _ar):
    if hasattr(_m, "install_test_dependencies"):
        _m.install_test_dependencies = _install_test_dependencies
print("sandbox fix installed (workspace-first .pth + editable install)", flush=True)
# -------------------------------------------------------------------------------------------------

declared = validate_single_declared_model(AGENT_DIR)
adapters = discover_adapters(str(AGENT_DIR), adapter_extensions=ALLOWED_ADAPTER_EXTENSIONS)
ngpu = torch.cuda.device_count()
server = VllmServer(VllmConfig(
    model=str(MODEL), port=8000, host="127.0.0.1", tool_call_parser="gemma4", reasoning_parser="gemma4",
    max_model_len=32768, dtype="bfloat16", gpu_memory_utilization=0.80, enable_auto_tool_choice=True,
    enable_lora=True, max_loras=8, max_lora_rank=128, tensor_parallel_size=4 if ngpu >= 4 else max(1, ngpu),
    default_chat_template_kwargs={"enable_thinking": True}, startup_timeout=60 * 25,
), adapter_manifest=adapters)
server.start()
print(f"[{time.time() - T0:.0f}s] vLLM up on {ngpu} GPUs", flush=True)
# --- capture proxy (SFT data): log every chat request/response between harness and vLLM ---
import threading, urllib.request, urllib.error  # noqa: E401,E402
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer  # noqa: E402
CAPTURE = WORK / "results" / RUN_NAME / "capture.jsonl"
CAPTURE.parent.mkdir(parents=True, exist_ok=True)
_LOCK = threading.Lock()


class _Proxy(BaseHTTPRequestHandler):
    def _fwd(self, method):
        n = int(self.headers.get("Content-Length") or 0)
        body = self.rfile.read(n) if n else None
        req = urllib.request.Request("http://127.0.0.1:8000" + self.path, data=body, method=method,
                                     headers={k: v for k, v in self.headers.items() if k.lower() not in ("host", "content-length")})
        t0 = time.time()
        try:
            with urllib.request.urlopen(req, timeout=3600) as r:
                data, status, hdrs = r.read(), r.status, r.headers
        except urllib.error.HTTPError as e:
            data, status, hdrs = e.read(), e.code, e.headers
        self.send_response(status)
        for k, v in hdrs.items():
            if k.lower() not in ("transfer-encoding", "connection", "content-length"):
                self.send_header(k, v)
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)
        if self.path.endswith("/chat/completions") and body:
            rec = {"t": t0, "dt": time.time() - t0, "status": status, "request": json.loads(body)}
            try:
                rec["response"] = json.loads(data)
            except Exception:
                rec["response_raw"] = data[:2000].decode("utf-8", "replace")
            with _LOCK, open(CAPTURE, "a") as f:
                f.write(json.dumps(rec) + "\n")

    def do_POST(self):
        self._fwd("POST")

    def do_GET(self):
        self._fwd("GET")

    def log_message(self, *a):
        pass


threading.Thread(target=ThreadingHTTPServer(("127.0.0.1", 8001), _Proxy).serve_forever, daemon=True).start()
server.config.port = 8001  # registry -> proxy -> vLLM on 8000
models = server.create_model_registry(aliases=[declared, "gemma-4-31b-it-qat-w4a16-ct"], model_prefix="openai/", api_key="EMPTY")
server.config.port = 8000

raw = yaml.safe_load((AGENT_DIR / "eval_config.yaml").read_text()) if (AGENT_DIR / "eval_config.yaml").exists() else {}
ev = (raw or {}).get("evaluation", raw or {})
limits, gen = build_submission_limits()
results_dir = WORK / "results" / RUN_NAME
cfg = EvalConfig(
    tasks_path=DATA / "tasks.jsonl", snapshots_dir=DATA / "snapshots", results_dir=results_dir,
    submission_dir=AGENT_DIR, models=models, sandbox="subprocess",
    timeout_seconds=int(ev.get("timeout_seconds", 300)), max_time_minutes=float(ev.get("max_time_minutes", 60)),
    max_tool_calls=int(ev.get("max_tool_calls", 100)),
    max_turns=int(ev["max_turns"]) if ev.get("max_turns") is not None else None,
    task_ids=TASK_IDS or None, limits=limits, generation_constraints=gen, adapter_manifest=adapters,
    context_cache_config=ContextCacheConfig(min_tokens=2048, ttl_seconds=1800, cache_intervals=10),
    events_compaction_config=EventsCompactionConfig(compaction_interval=5, overlap_size=2, token_threshold=14336, event_retention_size=5),
    graph_dir=str(DATA / "graphs"), embeddings_dir=str(DATA / "embeddings"), wheels_dir=DATA / "wheels",
    concurrency=CONCURRENCY, display_mode="quiet",
)
res = asyncio.run(Evaluator(cfg).run())
summary = {"run": RUN_NAME, "resolved": res.resolved, "total": res.total, "rate": res.resolution_rate,
           "wall_seconds": round(time.time() - T0), "concurrency": CONCURRENCY}
print(json.dumps(summary), flush=True)
(results_dir / "kernel_summary.json").write_text(json.dumps(summary, indent=1))
server.stop()
